-- HOTHX console banner shown when the script is run.
-- The six-digit value is a visual run ID, not a verification code.
do
    local runId = math.random(100000, 999999)
    print(runId)
    print("<font color='rgb(0,145,255)' size='14'>HOTHX - https://discord.gg/2hQxD2Th3</font>")
end

-- ============================================================================
-- AUTO PARRY CAPTURE SYSTEM (REPLACED FROM PROVIDED HOTHXv8 SOURCE)
-- Capture/token extraction, remote dispatch and the original full-screen splash
-- replace the old SwordsController PRY upvalue/index-based patch in full.
-- A captured parry packet means client initialization, not server confirmation.
-- ============================================================================
local workspace = cloneref(game:GetService('Workspace'))
local _PARRY_PATCH, _HOTHX_startRemoteCapture = (function()
local _PARRY_PATCH = {
    ready = false,
    tokenFound = false,
    parryRemote = nil,
    capturedArgs = nil,
    notified = false,
}

local replicated_storage = cloneref(game:GetService('ReplicatedStorage'))
local _token = nil
local _reverted = {}
local _original = {}
local HOTHX_showBypassSplash = nil

-- Token construction adapted from the reference HOTHXv8 file.
local function _tokenize(remote_uid)
    local time = tostring(math.floor(workspace:GetServerTimeNow() * 100))
    local key = _token(remote_uid, 'TIME')
    if type(key) ~= 'string' or #key == 0 then error('missing parry token key') end
    local characters = table.create(#time)
    for index = 1, #time do
        characters[index] = string.char(bit32.bxor(
            (string.byte(time, index) + index) % 256,
            string.byte(key, (index - 1) % #key + 1)
        ))
    end
    return table.concat(characters)
end

-- Keep the packet shape limited to actual parry events so unrelated remotes
-- cannot trigger the splash in this merged script.
local function _is_valid(args)
    return #args == 8
       and type(args[2]) == 'string'
       and type(args[3]) == 'string'
       and type(args[4]) == 'number'
       and typeof(args[5]) == 'CFrame'
       and type(args[6]) == 'table'
       and type(args[7]) == 'table'
       and type(args[8]) == 'boolean'
end

local function _hook(remote)
    if not remote or _reverted[remote] then return end
    local meta = getrawmetatable(remote)
    if not meta or _original[meta] then return end
    _original[meta] = true
    setreadonly(meta, false)
    local oldIndex = meta.__index
    meta.__index = function(self, key)
        if (key == 'FireServer' and self:IsA('RemoteEvent')) or
           (key == 'InvokeServer' and self:IsA('RemoteFunction')) then
            return function(_, ...)
                local args = {...}
                if _is_valid(args) and not _PARRY_PATCH.capturedArgs then
                    _reverted[self] = args
                    _PARRY_PATCH.capturedArgs = args
                    _PARRY_PATCH.parryRemote = self
                    _PARRY_PATCH.ready = _PARRY_PATCH.tokenFound
                end
                return oldIndex(self, key)(_, unpack(args))
            end
        end
        return oldIndex(self, key)
    end
    setreadonly(meta, true)
end

-- This initializer is called after the GUI has been created, as in the source.
local function _HOTHX_startRemoteCapture()
    local ok, err = pcall(function()
        if type(getgc) ~= 'function' or not debug or
           type(debug.info) ~= 'function' or
           type(debug.getupvalues) ~= 'function' then
            warn('[HOTHX] Executor missing getgc/debug inspection')
            return
        end
        for _, Function in pairs(getgc(true)) do
            if type(Function) == 'function' then
                local sourceOk, source = pcall(debug.info, Function, 's')
                if sourceOk and type(source) == 'string' and source:find('PRY', 1, true) then
                    local upOk, upvalues = pcall(debug.getupvalues, Function)
                    if upOk and type(upvalues) == 'table' then
                        for _, value in pairs(upvalues) do
                            if type(value) == 'function' then
                                _token = value
                                _PARRY_PATCH.tokenFound = true
                                break
                            end
                        end
                    end
                    if _token then break end
                end
            end
        end
        if not _PARRY_PATCH.tokenFound then
            warn('[HOTHX] PRY token not found; Parry capture not ready')
            return
        end
        for _, remote in pairs(replicated_storage:GetDescendants()) do
            if remote:IsA('RemoteEvent') or remote:IsA('RemoteFunction') then
                _hook(remote)
            end
        end
    end)
    if not ok then
        warn('[HOTHX] Parry capture initialization failed:', tostring(err))
        return
    end
    if not _PARRY_PATCH.tokenFound then return end
    task.spawn(function()
        while not _PARRY_PATCH.capturedArgs or not _PARRY_PATCH.parryRemote do
            task.wait(1)
        end
        _PARRY_PATCH.ready = true
        if not _PARRY_PATCH.notified and type(HOTHX_showBypassSplash) == 'function' then
            _PARRY_PATCH.notified = true
            HOTHX_showBypassSplash()
        end
    end)
end

-- Adapter for existing HOTHX Auto Parry/Manual Parry callers.
-- Packet layout and FireServer/InvokeServer dispatch are taken from HOTHXv8.
function _PARRY_PATCH.fire(curveCFrame, screenPositions, mouseLocation)
    if not _PARRY_PATCH.ready or not _PARRY_PATCH.parryRemote or
       not _PARRY_PATCH.capturedArgs or not _token then
        return false
    end
    local captured = _PARRY_PATCH.capturedArgs
    local packetOk, packet = pcall(function()
        return {
            captured[1],
            captured[2],
            _tokenize(captured[2]),
            0.5,
            curveCFrame or workspace.CurrentCamera.CFrame,
            screenPositions or {},
            mouseLocation or {},
            false,
        }
    end)
    if not packetOk then
        warn('[HOTHX] Parry token generation failed:', tostring(packet))
        return false
    end
    local fireOk, fireErr = pcall(function()
        if _PARRY_PATCH.parryRemote:IsA('RemoteEvent') then
            _PARRY_PATCH.parryRemote:FireServer(unpack(packet))
        elseif _PARRY_PATCH.parryRemote:IsA('RemoteFunction') then
            _PARRY_PATCH.parryRemote:InvokeServer(unpack(packet))
        end
    end)
    if not fireOk then warn('[HOTHX] Parry remote call failed:', tostring(fireErr)) end
    return fireOk
end

-- Fullscreen anti-cheat capture status from the same reference file.

local function HOTHX_base64Decode(data)
    local alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data = tostring(data or ''):gsub('[^' .. alphabet .. '=]', '')
    return (data:gsub('.', function(x)
        if x == '=' then return '' end
        local index = alphabet:find(x, 1, true) - 1
        local bits = ''
        for i = 6, 1, -1 do
            bits = bits .. (((index % 2^i) - (index % 2^(i - 1)) > 0) and '1' or '0')
        end
        return bits
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if #x ~= 8 then return '' end
        local value = 0
        for i = 1, 8 do
            if x:sub(i, i) == '1' then
                value = value + 2^(8 - i)
            end
        end
        return string.char(value)
    end))
end

