    local HOTHX_SPLASH_ASSET = nil
    local HOTHX_SPLASH_IS_SHOWING = false

    local function getMemeAsset()
        if HOTHX_SPLASH_ASSET then return HOTHX_SPLASH_ASSET end
        local loader = nil
        if type(getsynasset) == "function" then
            loader = getsynasset
        elseif type(getcustomasset) == "function" then
            loader = getcustomasset
        elseif syn and type(syn.asset) == "function" then
            loader = syn.asset
        end
        if type(loader) ~= "function" then return nil end

        local exists = false
        if type(isfile) == "function" then
            local ok, result = pcall(isfile, HOTHX_SPLASH_FILE)
            exists = ok and result == true
        end
        if not exists and type(writefile) == "function" then
            local ok, bytes = pcall(HOTHX_base64Decode, HOTHX_SPLASH_B64)
            if ok and type(bytes) == "string" and #bytes > 1000 then
                pcall(writefile, HOTHX_SPLASH_FILE, bytes)
            end
        end

        local ok, asset = pcall(loader, HOTHX_SPLASH_FILE)
        if ok and type(asset) == "string" and #asset > 0 then
            HOTHX_SPLASH_ASSET = asset
        end
        return HOTHX_SPLASH_ASSET
    end

    HOTHX_showBypassSplash = function()
        if HOTHX_SPLASH_IS_SHOWING then return end
        HOTHX_SPLASH_IS_SHOWING = true
        task.spawn(function()
            -- Work in a separate task so rendering other UI is not blocked.
            local ok, err = pcall(function()
                local asset = getMemeAsset()
                local parent = game:GetService("CoreGui") or LocalPlayer:FindFirstChildOfClass("PlayerGui")
                if not parent then return end
                local old = parent:FindFirstChild("HOTHX_FullscreenBypassSplash")
                if old then old:Destroy() end

                local splash = Instance.new("ScreenGui")
                splash.Name = "HOTHX_FullscreenBypassSplash"
                splash.ResetOnSpawn = false
                splash.IgnoreGuiInset = true
                splash.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                splash.DisplayOrder = 12000
                splash.Parent = parent

                local background = Instance.new("Frame")
                background.Name = "FullscreenBackdrop"
                background.BackgroundColor3 = Color3.fromRGB(8, 5, 10)
                background.BackgroundTransparency = 1
                background.BorderSizePixel = 0
                background.Size = UDim2.fromScale(1, 1)
                background.ZIndex = 1
                background.Parent = splash

                local front
                local behind
                local fallback
                if asset then
                    -- A dim crop fills the screen; the main image is FIT so
                    -- no Khmer or English words are cropped on PC/mobile.
                    behind = Instance.new("ImageLabel")
                    behind.Name = "AmbientFullScreenImage"
                    behind.BackgroundTransparency = 1
                    behind.Position = UDim2.fromScale(0, 0)
                    behind.Size = UDim2.fromScale(1, 1)
                    behind.ScaleType = Enum.ScaleType.Crop
                    behind.Image = asset
                    behind.ImageColor3 = Color3.fromRGB(83, 55, 68)
                    behind.ImageTransparency = 1
                    behind.ZIndex = 2
                    behind.Parent = background

                    front = Instance.new("ImageLabel")
                    front.Name = "UserMemePortrait"
                    front.AnchorPoint = Vector2.new(0.5, 0.5)
                    front.Position = UDim2.fromScale(0.5, 0.5)
                    front.Size = UDim2.fromScale(0.72, 0.72)
                    front.BackgroundTransparency = 1
                    front.ScaleType = Enum.ScaleType.Fit
                    front.Image = asset
                    front.ImageTransparency = 1
                    front.ZIndex = 3
                    front.Parent = background
                else
                    -- Some executors do not support local file-backed images.
                    -- Still display a temporary full-screen status card.
                    fallback = Instance.new("TextLabel")
                    fallback.Name = "UnsupportedAssetFallback"
                    fallback.Size = UDim2.fromScale(1, 1)
                    fallback.BackgroundTransparency = 1
                    fallback.Text = "ANTI-CHEAT BYPASSED\nដំណើរការហើយអាប៉ូយ"
                    fallback.Font = Enum.Font.GothamBold
                    fallback.TextScaled = true
                    fallback.TextWrapped = true
                    fallback.TextColor3 = Color3.fromRGB(255, 177, 54)
                    fallback.TextTransparency = 1
                    fallback.ZIndex = 3
                    fallback.Parent = background
                end

                local easeIn = TweenInfo.new(0.38, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
                TweenService:Create(background, easeIn, {BackgroundTransparency = 0.02}):Play()
                if behind then
                    TweenService:Create(behind, easeIn, {ImageTransparency = 0.68}):Play()
                end
                if front then
                    TweenService:Create(front, easeIn, {
                        ImageTransparency = 0,
                        Size = UDim2.fromScale(1, 1),
                    }):Play()
                end
                if fallback then
                    TweenService:Create(fallback, easeIn, {TextTransparency = 0}):Play()
                end

                task.wait(3)
                local easeOut = TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
                local finish = TweenService:Create(background, easeOut, {BackgroundTransparency = 1})
                if front then TweenService:Create(front, easeOut, {ImageTransparency = 1}):Play() end
                if behind then TweenService:Create(behind, easeOut, {ImageTransparency = 1}):Play() end
                if fallback then TweenService:Create(fallback, easeOut, {TextTransparency = 1}):Play() end
                finish:Play()
                finish.Completed:Wait()
                splash:Destroy()
            end)
            if not ok then warn("[HOTHX] Full-screen splash failed:", err) end
            HOTHX_SPLASH_IS_SHOWING = false
        end)
    end
end)()

return _PARRY_PATCH, _HOTHX_startRemoteCapture
end)()

