            function ModuleManager:change_state(state: boolean)
                self._state = state

                if self._state then
                    TweenService:Create(Module, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2.fromOffset(241, 93 + self._size + self._multiplier)
                    }):Play()

                    TweenService:Create(Toggle, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        BackgroundColor3 = Color3.fromRGB(205, 205, 220)
                    }):Play()

                    TweenService:Create(Circle, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        BackgroundColor3 = Color3.fromRGB(245, 245, 250),
                        Position = UDim2.fromScale(0.53, 0.5)
                    }):Play()
                else
                    TweenService:Create(Module, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2.fromOffset(241, 93)
                    }):Play()

                    TweenService:Create(Toggle, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        BackgroundColor3 = Color3.fromRGB(44, 44, 52)
                    }):Play()

                    TweenService:Create(Circle, TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        BackgroundColor3 = Color3.fromRGB(120, 120, 132),
                        Position = UDim2.fromScale(0, 0.5)
                    }):Play()
                end

                Library._config._flags[settings.flag] = self._state
                Config:save(game.GameId, Library._config)

                settings.callback(self._state)
            end
            
            function ModuleManager:connect_keybind()
                if not Library._config._keybinds[settings.flag] then
                    return
                end

                Connections[settings.flag..'_keybind'] = UserInputService.InputBegan:Connect(function(input: InputObject, process: boolean)
                    if process or Library._choosing_keybind then
                        return
                    end

                    if tostring(input.KeyCode) ~= Library._config._keybinds[settings.flag] then
                        return
                    end
                    
                    self:change_state(not self._state)
                end)
            end

            function ModuleManager:scale_keybind(empty: boolean)
                if Library._config._keybinds[settings.flag] and not empty then
                    local keybind_string = string.gsub(tostring(Library._config._keybinds[settings.flag]), 'Enum.KeyCode.', '')

                    local font_params = Instance.new('GetTextBoundsParams')
                    font_params.Text = keybind_string
                    font_params.Font = Font.new('rbxasset://fonts/families/Montserrat.json', Enum.FontWeight.Bold)
                    font_params.Size = 10
                    font_params.Width = 10000
            
                    local font_size = TextService:GetTextBoundsAsync(font_params)
                    
                    Keybind.Size = UDim2.fromOffset(math.max(39, font_size.X + 12), 17)
                    TextLabel.Size = UDim2.fromOffset(math.max(29, font_size.X + 2), 13)
                else
                    Keybind.Size = UDim2.fromOffset(39, 17)
                    TextLabel.Size = UDim2.fromOffset(31, 13)
                end
            end

            if Library:flag_type(settings.flag, 'boolean') then
                ModuleManager._state = true
                pcall(function()
                    settings.callback(ModuleManager._state)
                end)

                Toggle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                Circle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                Circle.Position = UDim2.fromScale(0.53, 0.5)
            end

            if Library._config._keybinds[settings.flag] then
                local keybind_string = string.gsub(tostring(Library._config._keybinds[settings.flag]), 'Enum.KeyCode.', '')
                TextLabel.Text = keybind_string

                ModuleManager:connect_keybind()
                ModuleManager:scale_keybind()
            end

            -- UI keybind: click the "None"/key chip, then press any keyboard key.
            -- Backspace/Delete clears it; Escape cancels. Works for every module.
            local function show_keybind_value()
                local saved = Library._config._keybinds[settings.flag]
                TextLabel.Text = saved and tostring(saved):gsub('Enum.KeyCode.', '') or 'None'
                TextLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
                ModuleManager:scale_keybind(not saved)
            end

            local function choose_keybind()
                if Library._choosing_keybind then return end
                Library._choosing_keybind = true
                Keybind.Size = UDim2.fromOffset(91, 17)
                TextLabel.Size = UDim2.fromOffset(82, 13)
                TextLabel.Text = 'Press a key...'
                TextLabel.TextColor3 = Color3.fromRGB(245, 245, 250)

                if Connections['keybind_choose_start'] then
                    Connections['keybind_choose_start']:Disconnect()
                    Connections['keybind_choose_start'] = nil
                end
                Connections['keybind_choose_start'] = UserInputService.InputBegan:Connect(function(input)
                    if input.UserInputType ~= Enum.UserInputType.Keyboard
                        or input.KeyCode == Enum.KeyCode.Unknown then
                        return
                    end

                    local key = input.KeyCode
                    if key ~= Enum.KeyCode.Escape then
                        if key == Enum.KeyCode.Backspace or key == Enum.KeyCode.Delete then
                            Library._config._keybinds[settings.flag] = nil
                        else
                            Library._config._keybinds[settings.flag] = tostring(key)
                        end
                        Config:save(game.GameId, Library._config)

                        if Connections[settings.flag..'_keybind'] then
                            Connections[settings.flag..'_keybind']:Disconnect()
                            Connections[settings.flag..'_keybind'] = nil
                        end
                        ModuleManager:connect_keybind()
                    end

                    if Connections['keybind_choose_start'] then
                        Connections['keybind_choose_start']:Disconnect()
                        Connections['keybind_choose_start'] = nil
                    end
                    show_keybind_value()
                    -- Don't trigger a module using the key being assigned.
                    task.defer(function() Library._choosing_keybind = false end)
                end)
            end

            Keybind.MouseButton1Click:Connect(choose_keybind)
            -- Also support the original middle-click shortcut.
            Connections[settings.flag..'_input_began'] = Header.InputBegan:Connect(function(input: InputObject)
                if input.UserInputType == Enum.UserInputType.MouseButton3 then
                    choose_keybind()
                end
            end)

            Header.MouseButton1Click:Connect(function()
                if Library._choosing_keybind then return end
                ModuleManager:change_state(not ModuleManager._state)
            end)

