    ['TF2 Critical'] = 'rbxassetid://296102734',
    Saber = 'rbxassetid://8415678813',
    Bameware = 'rbxassetid://3124331820'
}

local hit_sounds_module = PlayerTab:create_module({
    title = 'Hit Sounds',
    flag = 'Hit_Sounds',
    description = 'Toggles hit sounds',
    section = 'right',
    callback = function(value: boolean)
        hit_Sound_Enabled = value
    end
})

hit_sounds_module:create_slider({
    title = 'Volume',
    flag = 'HitSoundVolume',
    minimum_value = 1,
    maximum_value = 10,
    value = 5,
    round_number = true,
    callback = function(value)
        hit_Sound.Volume = value
    end
})

hit_sounds_module:create_dropdown({
    title = 'Hit Sound Type',
    flag = 'hit_sound_type',
    options = hitSoundOptions,
    maximum_options = #hitSoundOptions,
    multi_dropdown = false,
    callback = function(selectedOption)
        if hitSoundIds[selectedOption] then
            hit_Sound.SoundId = hitSoundIds[selectedOption]
        else
            warn('Invalid hit sound selection: ' .. tostring(selectedOption))
        end
    end
})

ReplicatedStorage.Remotes.ParrySuccess.OnClientEvent:Connect(function()
    if hit_Sound_Enabled then
        hit_Sound:Play()
    end
end)

local ability_esp_module = VisualsTab:create_module({
    title = "Ability ESP",
    description = "Displays equipped abilities above players",
    flag = "AbilityESPModule",
    section = "right",
    callback = function(state)
        if state then
            start_ability_esp()
        else
            stop_ability_esp()
        end

    end
})


end

setup_late_feature_modules()

local no_render_module = MiscTab:create_module({
    title = 'No Render',
    flag = 'No_Render',
    description = 'Disables Rendering of Effects',
    section = 'left',
    callback = function(state: boolean)
        getgenv().No_Render = state

        local playerScripts = Players.LocalPlayer:FindFirstChild('PlayerScripts')
        local effectScripts = playerScripts and playerScripts:FindFirstChild('EffectScripts')
        local clientFX = effectScripts and effectScripts:FindFirstChild('ClientFX')

        if clientFX then
            clientFX.Disabled = state
        end

        if state then
            if not Connections_Manager['No Render'] then
                local runtime = workspace:FindFirstChild('Runtime')
                if runtime then
                    Connections_Manager['No Render'] = runtime.ChildAdded:Connect(function(value)
                        Debris:AddItem(value, 0)
                    end)
                end
            end
        else
            if Connections_Manager['No Render'] then
                Connections_Manager['No Render']:Disconnect()
                Connections_Manager['No Render'] = nil
            end
        end
    end
})



-- VISUAL SKIN ONLY: Original gameplay/features above remain unchanged.
-- Separate function scope prevents the 200-local-register compiler error.
;(function()
--[[
    RAY STYLE - UI-only visual skin
    Based on the attached video. Appended to the original Zure/Azure script.
    Does not change the existing callbacks, remotes, or feature logic.
]]
do
    local _rayGui = library and library._ui
    local _rayContainer = _rayGui and _rayGui:FindFirstChild('Container')
    local _rayHandler = _rayContainer and _rayContainer:FindFirstChild('Handler')

    if _rayGui and _rayContainer and _rayHandler then
        local _rayTween = game:GetService('TweenService')
        local _rayInput = game:GetService('UserInputService')
        local _rayPlayers = game:GetService('Players')
        local _rayCamera = workspace.CurrentCamera
        local c = function(r,g,b) return Color3.fromRGB(r,g,b) end
        local theme = {
            bg=c(8,9,10), sidebar=c(9,10,12), card=c(11,12,14),
            raised=c(16,17,20), border=c(30,33,38),
            text=c(220,222,229), muted=c(104,108,120),
            active=c(242,243,248), track=c(61,64,71)
        }
        local function make(kind, props, parent)
            local obj = Instance.new(kind)
            for key,value in pairs(props) do obj[key] = value end
            obj.Parent = parent
            return obj
        end
        local function round(parent, radius)
            local corner = parent:FindFirstChildOfClass('UICorner') or Instance.new('UICorner')
            corner.CornerRadius = UDim.new(0, radius)
            corner.Parent = parent
        end
        local function line(parent)
            local st = parent:FindFirstChildOfClass('UIStroke') or Instance.new('UIStroke')
            st.Color = theme.border
            st.Transparency = 0.08
            st.Thickness = 0.8
            st.Parent = parent
        end

        -- Main geometry: ~700 x 480 px, just like the reference video.
        _rayContainer.Size = UDim2.fromOffset(700,480)
        -- Dark acrylic appearance; keep original AcrylicBlur.new(Container) active.
        _rayContainer.BackgroundColor3 = c(16,18,21)
        _rayContainer.BackgroundTransparency = 0.54
        _rayContainer.BorderSizePixel = 0
        round(_rayContainer, 11)
        line(_rayContainer)
        -- Fixed black outline; never changes with Accent hue.
        local outerStroke = _rayContainer:FindFirstChildOfClass('UIStroke')
        if outerStroke then
            outerStroke.Color = Color3.fromRGB(0,0,0)
            outerStroke.Transparency = 0
            outerStroke.Thickness = 1
        end
        _rayHandler.Size = UDim2.fromOffset(700,480)
        _rayHandler.BackgroundTransparency = 1
        for _, child in ipairs(_rayContainer:GetChildren()) do
            if child:IsA('UIGradient') then child.Enabled = false end
            if child.Name == 'GradientSide' then child.Visible = false end
        end
        if _rayHandler:FindFirstChild('Divider') then
            local divider = _rayHandler.Divider
            divider.Position = UDim2.fromOffset(164,0)
            divider.Size = UDim2.fromOffset(1,480)
            divider.BackgroundColor3 = theme.border
            divider.BackgroundTransparency = 0.4
            local grd = divider:FindFirstChildOfClass('UIGradient')
            if grd then grd.Enabled = false end
        end

        -- HOTHX branding (replaces the previous V Ray heading).
        local oldIcon = _rayHandler:FindFirstChild('AzureIcon')
        if oldIcon then oldIcon.Visible = false end
        local oldName = _rayHandler:FindFirstChild('ClientName')
        if oldName then
            oldName.Text = 'HOTHX'
            oldName.Position = UDim2.fromOffset(13,13)
            oldName.Size = UDim2.fromOffset(88,26)
            oldName.AnchorPoint = Vector2.new(0,0)
            oldName.TextSize = 14
            oldName.TextColor3 = theme.text
            oldName.Font = Enum.Font.GothamBold
            oldName.TextXAlignment = Enum.TextXAlignment.Left
            oldName.TextYAlignment = Enum.TextYAlignment.Center
