            local function decodeBase64(str)
                local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
                local values = {}
                for i = 1, #alphabet do
                    values[string.byte(alphabet, i)] = i - 1
                end
                local bytes, buffer, bitCount = {}, 0, 0
                for i = 1, #str do
                    local n = values[string.byte(str, i)]
                    if n ~= nil then
                        buffer = bit32.bor(bit32.lshift(buffer, 6), n)
                        bitCount = bitCount + 6
                        if bitCount >= 8 then
                            bitCount = bitCount - 8
                            bytes[#bytes + 1] = string.char(
                                bit32.band(bit32.rshift(buffer, bitCount), 255)
                            )
                            buffer = bit32.band(buffer, 2 ^ bitCount - 1)
                        end
                    end
                end
                return table.concat(bytes)
            end

            local ok, result = pcall(function()
                local path = "HOTHX_Graveyard_Logo.png"
                writefile(path, decodeBase64(encoded))
                return assetLoader(path)
            end)
            if ok and type(result) == "string" and result ~= "" then
                return result
            end
            return nil
        end

        if oldName then
            local imageId = loadHothxLogo()
            if imageId then
                local brand = Instance.new("ImageLabel")
                brand.Name = "GraveyardCrimesHOTHX"
                brand.BackgroundTransparency = 1
                brand.BorderSizePixel = 0
                brand.Size = UDim2.fromScale(1, 1)
                brand.Position = UDim2.fromScale(0, 0)
                brand.ScaleType = Enum.ScaleType.Fit
                brand.Image = imageId
                brand.ImageColor3 = Color3.fromRGB(255, 255, 255)
                brand.Active = false
                brand.ZIndex = oldName.ZIndex + 1
                brand.Parent = oldName
                oldName.Text = ""
            end
        end

        local mini = _rayHandler:FindFirstChild('Minimize')
        if mini then
            -- Remove the separate left-side minimize control.
            mini.Visible = false
        end

        -- Sidebar layout & category labels. Extra original tabs remain scrollable.
        local tabs = _rayHandler:FindFirstChild('Tabs')
        local tabMap = {
            Main={'Combat',1}, Misc={'Misc',2},
            Detection={'Detection',3}, Visual={'Visuals',4}
        }
        -- Reference-style monochrome ICONS. Drawn with Roblox GUI primitives,
        -- not Unicode glyphs: they render consistently across PC and mobile.
        local function drawRayTabIcon(tab, kind)
            local ink = theme.muted
            local holder = make('Frame', {
                Name='RayTabGlyph', BackgroundTransparency=1, BorderSizePixel=0,
                Position=UDim2.fromOffset(10,10), Size=UDim2.fromOffset(20,18),
                ZIndex=5
            }, tab)
            local function bar(x1,y1,x2,y2,thickness)
                local dx,dy=x2-x1,y2-y1
                local length=math.sqrt(dx*dx+dy*dy)
                local part=make('Frame',{
                    Name='RayIconInk', BackgroundColor3=ink,
                    BorderSizePixel=0,AnchorPoint=Vector2.new(.5,.5),
                    Position=UDim2.fromOffset((x1+x2)/2,(y1+y2)/2),
                    Size=UDim2.fromOffset(length,thickness or 1.6),
                    Rotation=math.deg(math.atan2(dy,dx)),ZIndex=6
                },holder)
                round(part,2)
                return part
            end
            local function dot(x,y,r)
                local part=make('Frame',{
                    Name='RayIconInk', BackgroundColor3=ink,
                    BorderSizePixel=0,AnchorPoint=Vector2.new(.5,.5),
                    Position=UDim2.fromOffset(x,y),
                    Size=UDim2.fromOffset(r*2,r*2),ZIndex=6
                },holder)
                round(part,100)
                return part
            end
            local function outline(x,y,w,h,strokeWidth,radius)
                local f=make('Frame',{
                    Name='RayIconOutline',BackgroundTransparency=1,
                    BorderSizePixel=0,Position=UDim2.fromOffset(x,y),
                    Size=UDim2.fromOffset(w,h),ZIndex=6
                },holder)
                round(f,radius or 100)
                local st=Instance.new('UIStroke')
                st.Name='RayIconStroke'
                st.Color=ink
                st.Thickness=strokeWidth or 1.5
                st.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
                st.Parent=f
                return f
            end
            if kind=='Main' then
                -- Crossed X as in Combat reference.
                bar(5,3,15,15,2.4)
                bar(15,3,5,15,2.4)
            elseif kind=='Detection' then
                -- Target circle with center dot.
                outline(3.5,2.5,13,13,1.5,100)
                dot(10,9,1.7)
            elseif kind=='Visual' then
                -- Capsule/eye with center dot.
                outline(2.5,4,15,10,1.5,7)
                dot(10,9,1.5)
            elseif kind=='Misc' then
                -- Three narrow menu lines.
                bar(4,4,16,4,1.4)
                bar(4,9,16,9,1.4)
                bar(4,14,16,14,1.4)
            elseif kind=='Player' then
                -- Minimal head-and-shoulders outline.
                outline(7.2,2,5.6,5.6,1.4,100)
                bar(4.5,15,6,11,1.4)
                bar(6,11,10,9.7,1.4)
                bar(10,9.7,14,11,1.4)
                bar(14,11,15.5,15,1.4)
            elseif kind=='Unlock' then
                -- Simple unlocked padlock.
                outline(5.5,8,10,8.5,1.4,3)
                bar(7,8,7,5.5,1.4)
                bar(7,5.5,9,3.5,1.4)
                bar(9,3.5,13,3.5,1.4)
                dot(10.5,12,1.1)
            else
                dot(10,9,2)
            end
            return holder
        end
        local function tintRayTabIcon(holder, color)
            for _, part in ipairs(holder:GetDescendants()) do
                if part:IsA('Frame') and part.Name=='RayIconInk' then
                    part.BackgroundColor3=color
                elseif part:IsA('UIStroke') and part.Name=='RayIconStroke' then
                    part.Color=color
                end
            end
        end

        local labelToTab = {}
        if tabs then
            tabs.Position = UDim2.fromOffset(17,72)
            tabs.Size = UDim2.fromOffset(139,348)
            tabs.CanvasSize = UDim2.fromOffset(0,0)
            tabs.AutomaticCanvasSize=Enum.AutomaticSize.Y
            tabs.ScrollBarThickness=0
            local ll = tabs:FindFirstChildOfClass('UIListLayout')
            if ll then ll.Padding = UDim.new(0,3) end
            for _,tab in ipairs(tabs:GetChildren()) do
                if tab:IsA('TextButton') and tab.Name == 'Tab' then
                    local name = tab:FindFirstChild('TextLabel')
                    if name then
                        local original = name.Text
                        local data = tabMap[original]
                        if data then
                            name.Text = data[1]
                            tab.LayoutOrder = data[2]
                            labelToTab[data[1]] = tab
                            local staleGlyph = tab:FindFirstChild('RayTabGlyph')
                            if staleGlyph then staleGlyph:Destroy() end
                            local originalIcon = tab:FindFirstChild('Icon')
                            if originalIcon and originalIcon:IsA('GuiObject') then
                                originalIcon.Visible = false
                            end
                            drawRayTabIcon(tab, original)
                        end
                        name.Position = UDim2.fromOffset(38,10)
                        name.AnchorPoint = Vector2.new(0,0)
                        name.Size = UDim2.fromOffset(92,17)
                        name.TextSize = 11
                        name.FontFace=Font.new('rbxasset://fonts/families/GothamSSm.json',Enum.FontWeight.Medium)
                        name.TextXAlignment=Enum.TextXAlignment.Left
                    end
                    tab.Size=UDim2.fromOffset(139,38)
                    tab.BackgroundColor3=theme.raised
                    round(tab,5)
                end
            end
        end

        local sections = _rayHandler:FindFirstChild('Sections')
        local sectionPairs = {}
        if sections then
            -- In the original library, each tab has a left/right ScrollingFrame pair.
            local scrolls = {}
            for _,obj in ipairs(sections:GetChildren()) do
                if obj:IsA('ScrollingFrame') then table.insert(scrolls,obj) end
            end
            for _, obj in ipairs(scrolls) do
                if obj.Name=='LeftSection' then
                    obj.AnchorPoint=Vector2.new(0,0)
                    obj.Position=UDim2.fromOffset(173,70)
                elseif obj.Name=='RightSection' then
                    obj.AnchorPoint=Vector2.new(0,0)
                    obj.Position=UDim2.fromOffset(433,70)
                end
                obj.Size=UDim2.fromOffset(244,410)
                obj.ScrollBarThickness=0
                obj.BackgroundTransparency=1
                obj.ClipsDescendants=true
                local ll=obj:FindFirstChildOfClass('UIListLayout')
                if ll then ll.Padding=UDim.new(0,10) end
            end
        end

        -- The source library animates selected tabs; this override keeps a black/gray style.
        library.update_tabs = function(self, selected)
            if not tabs then return end
            for _,t in ipairs(tabs:GetChildren()) do
                if t:IsA('TextButton') and t.Name=='Tab' then
                    local active=(t==selected)
                    t.BackgroundColor3=theme.raised
                    t.BackgroundTransparency=active and 0.2 or 1
                    local label=t:FindFirstChild('TextLabel')
                    if label then
                        label.TextColor3=active and theme.active or theme.muted
                        label.TextTransparency=0
                    end
                    local glyph=t:FindFirstChild('RayTabGlyph')
                    if glyph then tintRayTabIcon(glyph, active and theme.active or theme.muted) end
                    local stripe=t:FindFirstChild('RayActive')
                    if active then
                        if not stripe then
                            stripe=make('Frame',{
                                Name='RayActive',BackgroundColor3=theme.active,BorderSizePixel=0,
                                Position=UDim2.fromOffset(0,10),Size=UDim2.fromOffset(2,18)
                            },t)
                        end
                    elseif stripe then stripe:Destroy() end
                    local old=t:FindFirstChild('ActiveIndicator')
                    if old then old:Destroy() end
                end
            end
        end
        if labelToTab.Combat then library:update_tabs(labelToTab.Combat) end

        -- Cards inherit the same compact black look, without changing callbacks.
        local function restyle(obj)
            if obj:IsA('UIStroke') then
                local p=obj.Parent
                if p and (p.Name=='Module' or p.Name=='ModuleParagraph' or p.Name=='PlayerInfo') then
                    obj.Color=theme.border;obj.Transparency=0.05;obj.Thickness=0.8
                end
            elseif obj:IsA('Frame') then
                if obj.Name=='Module' or obj.Name=='ModuleParagraph' or obj.Name=='PlayerInfo' or obj.Name=='ImageModule' then
                    obj.BackgroundColor3=theme.card;obj.BackgroundTransparency=0
                    round(obj,5)
                elseif obj.Name=='Keybind' then
                    obj.BackgroundColor3=theme.raised;obj.BackgroundTransparency=0
                elseif obj.Name=='Box' then
                    obj.BackgroundColor3=theme.raised;obj.BackgroundTransparency=0.15
                elseif obj.Name=='Drag' then
                    obj.BackgroundColor3=theme.track;obj.BackgroundTransparency=0.15
                elseif obj.Name=='Toggle' then
                    obj.BackgroundTransparency=0.1
                elseif obj.Name=='Options' then
                    obj.BackgroundTransparency=1
                end
            elseif obj:IsA('TextLabel') then
                if obj.Name=='ModuleName' then
                    obj.TextColor3=theme.text;obj.TextTransparency=0;obj.TextSize=12
                elseif obj.Name=='Description' then
                    obj.TextColor3=theme.muted;obj.TextTransparency=0;obj.TextSize=9
                elseif obj.Name=='CurrentOption' or obj.Name=='Value' then
                    obj.TextColor3=theme.muted;obj.TextTransparency=0
                end
            elseif obj:IsA('ImageLabel') and obj.Name=='Icon' then
                obj.ImageColor3=theme.muted
            end
        end
        if sections then
            for _,obj in ipairs(sections:GetDescendants()) do restyle(obj) end
            sections.DescendantAdded:Connect(function(obj)
                -- UI elements added later are automatically skinned.
                task.defer(function()
                    if obj.Parent then restyle(obj) end
                end)
            end)
        end

        -- Floating search box (functional, filters all cards in the active tab).
        local searchOuter=make('Frame',{
            Name='RaySearchBox',BackgroundColor3=theme.card,
            BorderSizePixel=0,Position=UDim2.fromOffset(430,8),
            Size=UDim2.fromOffset(251,39),ZIndex=7
        },_rayHandler)
        round(searchOuter,11)
        line(searchOuter)
        -- Draw a real magnifying-glass icon with Roblox UI primitives.
        -- Text glyphs such as '⌕' can render as a square on some devices/fonts.
        local searchIcon = make('Frame',{
            Name='SearchMagnifier',Position=UDim2.fromOffset(13,11),
            Size=UDim2.fromOffset(19,19),BackgroundTransparency=1,ZIndex=8
        },searchOuter)
        local lens = make('Frame',{
            Name='Lens',Position=UDim2.fromOffset(1,1),
            Size=UDim2.fromOffset(10,10),BackgroundTransparency=1,
            BorderSizePixel=0,ZIndex=9
        },searchIcon)
        local lensCorner = Instance.new('UICorner')
        lensCorner.CornerRadius = UDim.new(1,0)
        lensCorner.Parent = lens
        local lensStroke = Instance.new('UIStroke')
        lensStroke.Name = 'LensOutline'
        lensStroke.Color = Color3.fromRGB(155,160,171)
        lensStroke.Thickness = 1.6
        lensStroke.Transparency = 0
        lensStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        lensStroke.Parent = lens
        local handle = make('Frame',{
            Name='MagnifierHandle',Position=UDim2.fromOffset(11,11),
            Size=UDim2.fromOffset(8,2),Rotation=45,
            BackgroundColor3=Color3.fromRGB(155,160,171),
            BorderSizePixel=0,ZIndex=9
        },searchIcon)
        local handleCorner = Instance.new('UICorner')
        handleCorner.CornerRadius = UDim.new(1,0)
        handleCorner.Parent = handle
        local search=make('TextBox',{
            Name='SearchInput',Position=UDim2.fromOffset(39,6),
            Size=UDim2.fromOffset(202,27),BackgroundTransparency=1,
            PlaceholderText='Search Functions...',PlaceholderColor3=c(86,89,99),
            Text='',ClearTextOnFocus=false,Font=Enum.Font.Gotham,
            TextSize=11,TextColor3=theme.text,TextXAlignment=Enum.TextXAlignment.Left,
            ZIndex=8
        },searchOuter)
        local oldSearch=_rayHandler:FindFirstChild('SearchButton')
        if oldSearch then oldSearch.Visible=false end
        local function applySearch()
            if not sections then return end
            local q=string.lower(search.Text)
            for _,col in ipairs(sections:GetChildren()) do
                if col:IsA('ScrollingFrame') then
                    for _,card in ipairs(col:GetChildren()) do
                        if card:IsA('GuiObject') and
                           (card.Name=='Module' or card.Name=='ModuleParagraph' or
                            card.Name=='PlayerInfo' or card.Name=='ImageModule') then
                            if q=='' then card.Visible=true
                            else
                                local names={}
                                for _,desc in ipairs(card:GetDescendants()) do
                                    if desc:IsA('TextLabel') and
                                       (desc.Name=='ModuleName' or desc.Name=='Description') then
                                        table.insert(names,desc.Text)
                                    end
                                end
                                card.Visible=string.find(string.lower(table.concat(names,' ')),q,1,true)~=nil
                            end
                        end
                    end
                end
            end
        end
        search:GetPropertyChangedSignal('Text'):Connect(applySearch)

        -- Account card is fixed to bottom of sidebar (rather than part of the lists).
        local acct=make('Frame',{
            Name='RayAccount',Position=UDim2.fromOffset(13,424),
            Size=UDim2.fromOffset(144,43),BackgroundColor3=theme.card,
            BorderSizePixel=0,ZIndex=7
        },_rayHandler)
        round(acct,9);line(acct)
        local portrait=make('ImageLabel',{
            Name='Portrait',Position=UDim2.fromOffset(8,7),
            Size=UDim2.fromOffset(29,29),BackgroundColor3=theme.raised,
            BorderSizePixel=0,Image='',ZIndex=8
        },acct)
        round(portrait,7)
        local player=_rayPlayers.LocalPlayer
        make('TextLabel',{
            Name='DisplayName',Position=UDim2.fromOffset(45,9),
            Size=UDim2.fromOffset(92,12),BackgroundTransparency=1,
            Text=player and player.DisplayName or 'Player',
            TextColor3=theme.text,Font=Enum.Font.GothamMedium,
            TextSize=10,TextTruncate=Enum.TextTruncate.AtEnd,
            TextXAlignment=Enum.TextXAlignment.Left,ZIndex=8
        },acct)
        make('TextLabel',{
            Name='Username',Position=UDim2.fromOffset(45,22),
            Size=UDim2.fromOffset(94,13),BackgroundTransparency=1,
            Text=player and ('@'..player.Name) or '@player',
            TextColor3=theme.muted,Font=Enum.Font.Gotham,
            TextSize=9,TextTruncate=Enum.TextTruncate.AtEnd,
            TextXAlignment=Enum.TextXAlignment.Left,ZIndex=8
        },acct)
        if player then
            task.spawn(function()
                local ok,url=pcall(function()
                    return _rayPlayers:GetUserThumbnailAsync(player.UserId,Enum.ThumbnailType.HeadShot,Enum.ThumbnailSize.Size48x48)
                end)
                if ok and portrait.Parent then portrait.Image=url end
            end)
        end

        -- Restore original toggle/minimize actions while keeping the new geometry.
        library.change_visiblity=function(self,state)
            _rayTween:Create(_rayContainer,TweenInfo.new(0.35,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{
                Size=state and UDim2.fromOffset(700,480) or UDim2.fromOffset(104,52)
            }):Play()
        end
        local uiScale=_rayContainer:FindFirstChildOfClass('UIScale')
        if uiScale then
            if Connections and Connections.disconnect then pcall(function() Connections:disconnect('ui_scale') end) end
            local function fit()
                local view=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
                if view then uiScale.Scale=math.clamp(math.min((view.X-20)/700,(view.Y-20)/480),0.45,1) end
            end
            fit()
            if _rayCamera then _rayCamera:GetPropertyChangedSignal('ViewportSize'):Connect(fit) end
        end
    end
end

end)()


