        local function decode(encoded)
            local alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            local lookup = {}
            for i=1,#alphabet do lookup[string.byte(alphabet,i)]=i-1 end
            local out,buffer,bits={},0,0
            for i=1,#encoded do
                local v=lookup[string.byte(encoded,i)]
                if v then
                    buffer=bit32.bor(bit32.lshift(buffer,6),v)
                    bits=bits+6
                    if bits>=8 then
                        bits=bits-8
                        out[#out+1]=string.char(bit32.band(bit32.rshift(buffer,bits),255))
                        buffer=bit32.band(buffer,2^bits-1)
                    end
                end
            end
            return table.concat(out)
        end

        local fontAsset=HOTHX_ATLAS_ASSET
        if fontAsset=='' then
            local localAsset=getcustomasset or getsynasset
            if type(localAsset)=='function' and type(writefile)=='function' then
                local ok,id=pcall(function()
                    local path='HOTHX_Text_Font_Atlas.png'
                    writefile(path,decode(packed))
                    return localAsset(path)
                end)
                if ok and type(id)=='string' and id~='' then fontAsset=id end
            end
        end
        if not fontAsset or fontAsset=='' then
            warn('[HOTHX FONT] Custom image loading unavailable. Upload HOTHX_Text_Font_Atlas.png and fill HOTHX_ATLAS_ASSET.')
            return
        end
        packed=nil -- release the embedded string when possible

        -- Glyph-only UI labels such as icons are intentionally excluded.
        local skip={RayTabGlyph=true,RayMark=true,SearchGlyph=true,ActiveIndicator=true}
        local registrations=setmetatable({}, {__mode='k'})

        local function isVisible(item)
            local node=item
            while node and node~=ui do
                if node:IsA('GuiObject') and not node.Visible then return false end
                node=node.Parent
            end
            return true
        end

        local function unwrap(value,rich)
            if rich then
                value=value:gsub('<[^>]->','')
                value=value:gsub('&lt;','<'):gsub('&gt;','>'):gsub('&amp;','&')
            end
            return value:gsub('\r','')
        end

        local function getProperty(obj,name,default)
            local ok,result=pcall(function() return obj[name] end)
            if ok then return result end
            return default
        end

        local function draw(item,entry)
            if not item.Parent then return end
            local host=entry.host
            if entry.focused then return end
            if not isVisible(item) then
                host.Visible=false
                return
            end
            local placeholder=(item:IsA('TextBox') and item.Text=='')
                and entry.placeholder or nil
            local value=unwrap(placeholder or item.Text or '',getProperty(item,'RichText',false))
            -- Unsupported international symbols (including icon glyphs) stay native.
            for index=1,#value do
                local b=string.byte(value,index)
                if b~=10 and b~=9 and (b<32 or b>126 or not glyphMap[b]) then
                    host.Visible=false
                    if item.TextTransparency==1 and entry.masked then
                        entry.lock=true
                        item.TextTransparency=entry.opacity
                        entry.lock=false
                        entry.masked=false
                    end
                    return
                end
            end

            local box=item.AbsoluteSize
            local available=math.max(1,box.X)
            local pixelSize=math.max(5,item.TextSize)
            local factor=pixelSize/64
            local lineHeight=pixelSize*1.2
            local lines={{}}
            local widths={0}
            local width=0
            local num=1
            local maxChars=260
            for i=1,math.min(#value,maxChars) do
                local b=string.byte(value,i)
                if b==10 then
                    num=num+1;lines[num]={};widths[num]=0;width=0
                else
                    local glyph=glyphMap[b==9 and 32 or b]
                    local advance=glyph[5]*factor
                    if item.TextWrapped and width+advance>available and #lines[num]>0 then
                        num=num+1;lines[num]={};widths[num]=0;width=0
                    end
                    lines[num][#lines[num]+1]=b==9 and 32 or b
                    width=width+advance
                    widths[num]=width
                end
            end
            if getProperty(item,'TextTruncate',nil)==Enum.TextTruncate.AtEnd
                and not item.TextWrapped and widths[1]>available then
                while #lines[1]>0 and widths[1]>available-pixelSize*1.5 do
                    local last=table.remove(lines[1])
                    widths[1]=widths[1]-glyphMap[last][5]*factor
                end
                for j=1,3 do
                    lines[1][#lines[1]+1]=46
                    widths[1]=widths[1]+glyphMap[46][5]*factor
                end
            end

            for _,child in ipairs(host:GetChildren()) do child:Destroy() end
            local occupied=num*lineHeight
            local top=0
            if item.TextYAlignment==Enum.TextYAlignment.Center then top=(box.Y-occupied)/2
            elseif item.TextYAlignment==Enum.TextYAlignment.Bottom then top=box.Y-occupied end
            local count=0
            for ln,chars in ipairs(lines) do
                local x=0
                if item.TextXAlignment==Enum.TextXAlignment.Center then x=(available-widths[ln])/2
                elseif item.TextXAlignment==Enum.TextXAlignment.Right then x=available-widths[ln] end
                for _,b in ipairs(chars) do
                    local glyph=glyphMap[b]
                    if glyph[3]>0 and glyph[4]>0 then
                        local char=Instance.new('ImageLabel')
                        char.Name='Letter'
                        char.BackgroundTransparency=1
                        char.BorderSizePixel=0
                        char.Image=fontAsset
                        char.ImageRectOffset=Vector2.new(glyph[1],glyph[2])
                        char.ImageRectSize=Vector2.new(glyph[3],glyph[4])
                        char.Position=UDim2.fromOffset(x+glyph[6]*factor,top+(ln-1)*lineHeight+glyph[7]*factor)
                        char.Size=UDim2.fromOffset(glyph[3]*factor,glyph[4]*factor)
                        char.ScaleType=Enum.ScaleType.Stretch
                        char.ImageColor3=placeholder
                            and getProperty(item,'PlaceholderColor3',item.TextColor3)
                            or item.TextColor3
                        char.ImageTransparency=entry.opacity
                        char.ZIndex=item.ZIndex+1
                        char.Active=false
                        char.Parent=host
                        count=count+1
                    end
                    x=x+glyph[5]*factor
                end
            end
            host.Visible=true
            if placeholder then
                -- Prevent the built-in placeholder from appearing behind our custom font.
                entry.lock=true
                item.PlaceholderText=''
                entry.lock=false
            end
            if not entry.masked then
                entry.masked=true
                entry.opacity=item.TextTransparency
            end
            entry.lock=true
            item.TextTransparency=1
            entry.lock=false
        end

        local function attach(item)
            if registrations[item] or skip[item.Name] then return end
            if not (item:IsA('TextLabel') or item:IsA('TextButton') or item:IsA('TextBox')) then return end
            -- A text label used exclusively as a symbol should not change.
            if #item.Text<=2 and (item.Text:find('[^%w%s]')~=nil) then return end
            local host=Instance.new('Frame')
            host.Name='HOTHX_Graveyard_Text'
            host.Size=UDim2.fromScale(1,1)
            host.Position=UDim2.fromScale(0,0)
            host.BackgroundTransparency=1
            host.ClipsDescendants=true
            host.Active=false
            host.ZIndex=item.ZIndex+1
            host.Parent=item
            local entry={host=host,opacity=item.TextTransparency,masked=false,focused=false,lock=false,
                placeholder=item:IsA('TextBox') and item.PlaceholderText or nil}
            registrations[item]=entry
            local function redraw() if item.Parent then draw(item,entry) end end
            local function recolor()
                for _,char in ipairs(host:GetChildren()) do
                    if char:IsA('ImageLabel') then char.ImageColor3=item.TextColor3 end
                end
            end
            for _,prop in ipairs({'Text','TextSize','TextXAlignment','TextYAlignment','TextWrapped','TextTruncate','AbsoluteSize','RichText'}) do
                pcall(function() item:GetPropertyChangedSignal(prop):Connect(redraw) end)
            end
            item:GetPropertyChangedSignal('TextColor3'):Connect(recolor)
            item:GetPropertyChangedSignal('TextTransparency'):Connect(function()
                if entry.lock or entry.focused then return end
                if item.TextTransparency~=1 then
                    entry.opacity=item.TextTransparency
                    for _,char in ipairs(host:GetChildren()) do
                        if char:IsA('ImageLabel') then char.ImageTransparency=entry.opacity end
                    end
                    entry.lock=true
                    item.TextTransparency=1
                    entry.lock=false
                end
            end)
            if item:IsA('TextBox') then
                item.Focused:Connect(function()
                    entry.focused=true
                    host.Visible=false
                    entry.lock=true
                    if entry.placeholder then item.PlaceholderText=entry.placeholder end
                    item.TextTransparency=entry.opacity
                    entry.lock=false
                end)
                item.FocusLost:Connect(function()
                    entry.focused=false
                    task.defer(redraw)
                end)
            end
            redraw()
        end

        local function scan(node)
            for _,obj in ipairs(node:GetDescendants()) do attach(obj) end
        end
        scan(ui)
        ui.DescendantAdded:Connect(function(obj)
            if obj.Name=='HOTHX_Graveyard_Text' or obj.Name=='Letter' then return end
            task.defer(function()
                if obj.Parent then attach(obj) end
            end)
        end)
        local tabSections=ui:FindFirstChild('Container')
        tabSections=tabSections and tabSections:FindFirstChild('Handler')
        tabSections=tabSections and tabSections:FindFirstChild('Sections')
        if tabSections then
            for _,section in ipairs(tabSections:GetChildren()) do
                if section:IsA('ScrollingFrame') then
                    section:GetPropertyChangedSignal('Visible'):Connect(function()
                        if section.Visible then
                            task.defer(function()
                                for _,obj in ipairs(section:GetDescendants()) do
                                    local entry=registrations[obj]
                                    if entry then draw(obj,entry) end
                                end
                            end)
                        end
                    end)
                end
            end
        end
        -- Also include the toasts, which live in their own ScreenGui.
        local notifications=game:GetService('CoreGui'):FindFirstChild('AzureNotificationRoot')
        if notifications then
            scan(notifications)
            notifications.DescendantAdded:Connect(function(obj)
                if obj.Name~='HOTHX_Graveyard_Text' and obj.Name~='Letter' then
                    task.defer(function() if obj.Parent then attach(obj) end end)
                end
            end)
        end
    end

    -- Disabled the all-text Graveyard atlas because it makes UI text look blurry.
    -- The main HOTHX logo/title remains styled separately; regular UI text stays clear.
end)()

return Library
